import json
import re

from prelegal_backend.config import REPO_DIR
from prelegal_backend.documents import registry

CATALOG = json.loads((REPO_DIR / "catalog.json").read_text(encoding="utf-8"))


def test_every_catalog_template_is_supported() -> None:
    used = {d.template for d in registry().documents}
    # The Mutual NDA cover page is generated by the app, not used as a template.
    expected = {t["filename"] for t in CATALOG["templates"]} - {"templates/Mutual-NDA-coverpage.md"}
    assert used == expected
    for doc in registry().documents:
        assert (REPO_DIR / doc.template).is_file()


def test_ids_and_field_keys_are_unique() -> None:
    ids = registry().ids
    assert len(ids) == len(set(ids)) == 11
    for doc in registry().documents:
        keys = [f.key for f in doc.fields]
        assert len(keys) == len(set(keys)), doc.id


def test_party_roles_expand_to_party_fields() -> None:
    csa = registry().get("csa")
    assert csa is not None
    assert [f.key for f in csa.fields[:5]] == [
        "provider.company",
        "provider.name",
        "provider.title",
        "provider.noticeAddress",
        "customer.company",
    ]
    assert csa.fields[0].label == "Provider company"
    assert csa.fields[0].required


def test_common_fields_are_resolved() -> None:
    csa = registry().get("csa")
    assert csa is not None
    law = next(f for f in csa.fields if f.key == "governingLaw")
    assert law.label == "Governing Law" and law.required and law.description


def test_choice_fields_have_options() -> None:
    for doc in registry().documents:
        for f in doc.fields:
            assert bool(f.options) == (f.kind == "choice"), (doc.id, f.key)
            assert re.fullmatch(r"[a-zA-Z0-9.]+", f.key), f.key
